import { mapState, mapMutations } from "vuex";
import { memberRight, memberRightSave, saveMemberContent } from "@/api/user";
import uploadPictures from "@/components/uploadPictures";
import WangEditor from "@/components/wangEditor/index.vue";

export default {
  components: { uploadPictures, WangEditor },
  data() {
    return {
      thead: [
        {
          title: "权益名称",
          key: "title",
        },
        {
          title: "展示名称",
          key: "show_title",
        },
        {
          title: "权益图标（80x80）",
          slot: "image",
        },
        {
          title: "权益简介",
          key: "explain",
        },
        {
          title: "权益状态",
          slot: "status",
        },
        {
          title: "操作",
          slot: "action",
        },
      ],
      tbody: [],
      loading: false,
      total: 0,
      page: 1,
      limit: 30,
      modal1: false,
      form: {
        id: "",
        right_type: "",
        title: "",
        show_title: "",
        image: "",
        explain: "",
        number: 1,
        status: 1,
      },
      rules: {
        title: [{ required: true, message: "请输入权益名称", trigger: "blur" }],
        show_title: [
          { required: true, message: "请输入展示名称", trigger: "blur" },
        ],
        image: [{ required: true, message: "请上传权益图标" }],
        explain: [
          { required: true, message: "请输入权益简介", trigger: "blur" },
        ],
        number: [{ required: true, type: "integer", message: "请输入正整数" }],
      },
      modal2: false,
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12,
      },
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8,
      },
      modal3: false,
      content: "",
      agreementCon: "",
    };
  },
  computed: {
    ...mapState("media", ["isMobile"]),
  },
  created() {
    this.getRightList();
  },
  methods: {
    getRightList() {
      this.loading = true;
      memberRight()
        .then((res) => {
          const { count, list } = res.data;
          this.loading = false;
          this.total = count;
          this.tbody = list;
        })
        .catch((err) => {
          this.loading = false;
          this.$Message.error(err);
        });
    },
    // 改变状态
    statusChange(row) {
      this.form.id = row.id;
      this.form.right_type = row.right_type;
      this.form.title = row.title;
      this.form.show_title = row.show_title;
      this.form.image = row.image;
      this.form.explain = row.explain;
      this.form.number = row.number;
      this.form.status = row.status;
      this.rightSave();
    },
    // 编辑
    edit(row) {
      this.modal1 = true;
      this.form.id = row.id;
      this.form.status = row.status;
      this.form.right_type = row.right_type;
      this.form.title = row.title;
      this.form.show_title = row.show_title;
      this.form.image = row.image;
      this.form.explain = row.explain;
      this.form.number = row.number;
    },
    // 分页
    pageChange(index) {
      this.page = index;
      this.getRightList();
    },
    // 修改
    rightSave() {
      memberRightSave(this.form)
        .then((res) => {
          this.modal1 = false;
          this.getRightList();
          this.$Message.success(res.msg);
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    formSubmit(name) {
      this.$refs[name].validate((valid) => {
        if (valid) {
          this.rightSave();
        }
      });
    },
    callImage() {
      this.modal2 = true;
    },
    getPic(image) {
      this.form.image = image.att_dir;
      this.modal2 = false;
    },
    editRight(row) {
      this.modal3 = true;
      this.form.id = row.id;
      this.content = row.content;
      this.agreementCon = row.content;
    },
    getEditorContent(content) {
      this.agreementCon = content;
    },
    saveMemberContent() {
      saveMemberContent(this.form.id, { content: this.agreementCon })
        .then((res) => {
          this.modal3 = false;
          this.$Message.success(res.msg);
          this.getRightList();
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    membercCancel(e) {
      if (!e) {
        this.$set(this, "agreementCon", "");
        this.$set(this, "content", "");
        this.modal3 = false;
      }
    },
  },
};
